 338	\begin{lemma}[Triangle inequality for ``$\simeq$''; Proposition 4.29 in \cite{Ji2020LowIndividualDegree}]\label{fact:triangle-for-simeq}
 339		\lean{MIPStarRE.QPBT.consistencyDefect_trans_le}
 340		\leanok
 341		\uses{def:consistency}
 342		If $A^x_a \ot \Id_B \simeq_{\eps} \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\gamma \Id_A \ot D^x_a$, then
 343		\[
 344			A^x_a \ot \Id_B \simeq_{\eps + 2\sqrt{\delta+\gamma}} \Id_A \ot D^x_a\,.
 345		\]
 346	\end{lemma}
 347	\begin{proof}
 348		\leanok
 349		\uses{fact:agreement, fact:triangle, lem:distance-overlap-gap,
 350			lem:distance-defect-overlap, lem:distance-symmetry}
 351		Stated in the source without proof; it is Proposition 4.29 of \cite{Ji2020LowIndividualDegree}. The two hypotheses involving $C$ convert, via Lemma~\ref{fact:agreement}, into state-dependent closeness of $C^x_a \ot \Id_B$ to both $\Id_A \ot B^x_a$ and $\Id_A \ot D^x_a$, hence of $\Id_A \ot B^x_a$ to $\Id_A \ot D^x_a$ at cost $O(\delta+\gamma)$. The first consistency then transfers from $B$ to $D$ by expanding the off-diagonal mass and applying the Cauchy--Schwarz inequality, which turns the squared-distance bound into the term $2\sqrt{\delta+\gamma}$.
 352	\end{proof}
