 354	\begin{lemma}[Data processing; Fact 4.26 in \cite{Natarajan2018NEEXP}]\label{fact:data-processing}
 355		\lean{MIPStarRE.QPBT.consistencyDefect_postprocess_le}
 356		\leanok
 357		\uses{def:consistency, def:bracket}
 358		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
 359		\[
 360			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
 361		\]
 362	\end{lemma}
 363	\begin{proof}
 364		\leanok
 365		\uses{def:distance-state-quadratic-form,
 366			lem:distance-consistency-term, lem:distance-point-defect,
 367			def:distance-left-placed-measurement,
 368			def:distance-right-placed-measurement,
 369			lem:distance-placed-product-qform,
 370			lem:distance-postprocess-overlap}
 371		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
 372	\end{proof}
