 374	The state-dependent distance is the right tool for reasoning about the closeness of measurement operators in a strategy. The following lemma converts joint consistency with a single projective measurement into an approximate commutation relation.
 375	
 376	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
 377		\lean{MIPStarRE.QPBT.opDistSq_commutator_le}
 378		\leanok
 379		\uses{def:povm-distance, def:povm-conventions}
 380		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
 381		\begin{align*}
 382			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
 383			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
 384		\end{align*}
 385		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
 386		\[
 387			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
 388		\]
 389	\end{lemma}
 390	\begin{proof}
 391		\leanok
 392		\uses{fact:add-a-proj, fact:triangle,
 393			lem:distance-left-fiber-contraction,
 394			lem:distance-right-fiber-contraction,
 395			lem:distance-joint-marginal-product,
 396			lem:distance-joint-marginal-product-rev,
 397			lem:distance-opposite-placements-commute, lem:distance-reindex,
 398			lem:distance-congr, lem:distance-congr-sub,
 399			def:distance-swap-last, lem:distance-swap-last-inverse,
 400			lem:distance-symmetry}
 401		Applying Lemma~\ref{fact:add-a-proj} to $C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,c}$ with the multiplier family $\{A^x_{a,\,b} \ot \Id_B\}$, we have
 402		\begin{equation}\label{eq:commutation-analysis-1}
 403			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
 404		\end{equation}
 405		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
 406		\begin{equation}\label{eq:commutation-analysis-2}
 407			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
 408		\end{equation}
 409		Combining \eqref{eq:commutation-analysis-1} and \eqref{eq:commutation-analysis-2} via Lemma~\ref{fact:triangle},
 410		\begin{equation}\label{eq:commutation-analysis-3}
 411			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
 412		\end{equation}
 413		A symmetric argument gives
 414		\begin{equation}\label{eq:commutation-analysis-4}
 415			C^x_{a,\,c}\, A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
 416		\end{equation}
 417		The claim follows by subtracting \eqref{eq:commutation-analysis-3} and \eqref{eq:commutation-analysis-4}.
 418	\end{proof}
