 427	\begin{lemma}[Sandwiched simultaneous measurement; modified from Fact 4.34 in \cite{Natarajan2018NEEXP}]\label{lem:ld-sandwich}
 428		\lean{MIPStarRE.QPBT.sandwichProduct}
 429		\lean{MIPStarRE.QPBT.sandwichProduct_isMeasurement}
 430		\lean{MIPStarRE.QPBT.consistencyDefect_sandwich_le}
 431		\leanok
 432		\uses{def:consistency, def:bracket, def:povm-conventions}
 433		Let $k \ge 0$ be an integer and let $\eps > 0$. Let $\mathcal X$ be a finite set and $\mu$ a distribution over $\mathcal X$, and let $\mathcal Y$ be a finite nonempty set; all statements below that sample $y \in \mathcal Y$ refer to the uniform distribution on $\mathcal Y$. For each $1 \le i \le k$ let $\mathcal R_i$ be a finite set, let $\mathcal G_i$ be a finite set of functions $g_i \colon \mathcal Y \to \mathcal R_i$, and for each $x \in \mathcal X$ let $\{G^{i,\,x}_g\}_{g \in \mathcal G_i}$ be a projective measurement. Suppose that for all $i \in \{1,\dots,k\}$ the set $\mathcal G_i$ satisfies the following property: for any two $g_i \ne g_i' \in \mathcal G_i$, the probability that $g_i(y) = g_i'(y)$ over a uniformly random $y \in \mathcal Y$ is at most $\eps$.
 434		Index the factors by $0,\ldots,k-1$; factor $r$ corresponds to the paper's
 435		factor $r+1$.
 436	
 437		Let $\bigl\{ A^x_{g_1,\,g_2,\,\dots,\,g_k} \bigr\}$ be a projective measurement with outcomes $(g_1,\dots,g_k) \in \mathcal G_1 \times \cdots \times \mathcal G_k$. Here $\operatorname{eval}_y$ denotes the evaluation map $g \mapsto g(y)$, so that $A^x_{[\operatorname{eval}_y(\cdot)_i = a_i]}$ post-processes the outcome tuple by evaluating its $i$-th component at $y$; since the outcome sets $\mathcal G_1 \times \cdots \times \mathcal G_k$ and $\mathcal G_i$ and the targets $\mathcal R_i$ are finite, these are post-processings in the sense of Definition~\ref{def:bracket}. For each $1 \le i \le k$, suppose that on average over $x \sim \mu$ and $y \in \mathcal Y$ sampled uniformly at random,
 438		\begin{equation}\label{eq:ld-sandwich-1}
 439			A^x_{[\operatorname{eval}_y(\cdot)_i = a_i]} \ot \Id_B \simeq_{\delta} \Id_A \ot G^{i,\,x}_{[\operatorname{eval}_y(\cdot) = a_i]}\,.
 440		\end{equation}
 441		% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:465-495) prints the
 442		% transposed pairing G^{k,x}_{g_1} ... G^{1,x}_{g_k} ... G^{k,x}_{g_1}, which is undefined
 443		% when the outcome sets differ; the pairing below is the one of Fact 4.34 in the NEEXP
 444		% source. The empty product for k = 0 is also made explicit here. See
 445		% rem:ld-sandwich-indexing.
 446		Define the POVM family $\{C^x_{g_1,\,g_2,\,\dots,\,g_k}\}$, for $x \in \mathcal X$, by
 447		\[
 448			C^x_{g_1,\,g_2,\,\dots,\,g_k} = G^{k,\,x}_{g_k} \cdots G^{2,\,x}_{g_2}\; G^{1,\,x}_{g_1}\; G^{2,\,x}_{g_2} \cdots G^{k,\,x}_{g_k}\,;
 449		\]
 450		for $k = 0$ the empty product is understood as the identity, so that $C^x$ is the measurement whose single outcome, the empty tuple, carries the operator $\Id$. Then on average over $x \sim \mu$ and $y \in \mathcal Y$ sampled uniformly at random,
 451		\begin{equation}\label{eq:ld-sandwich-2}
 452			A^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]} \ot \Id_B \simeq_{k(\delta+\eps)^{1/2}} \Id_A \ot C^x_{[\operatorname{eval}_y(\cdot) = (a_1,\,a_2,\,\dots,\,a_k)]}\,.
 453		\end{equation}
 454	\end{lemma}
 455	\begin{proof}
 456		The source proof is a citation: the argument is identical to the proof of Fact 4.34 in \cite{Natarajan2018NEEXP}, with the only modification being the insertion of the dependence on the question $x$ for all measurements considered. In outline, the consistency hypotheses \eqref{eq:ld-sandwich-1} allow one to insert the projective factors $G^{i,\,x}$ next to $A^x$ one index at a time, and the $\eps$-bound on the pairwise agreement of distinct functions in $\mathcal G_i$ controls the events on which two different outcomes collide at the sampled point $y$. Each of the $k$ insertions costs $(\delta+\eps)^{1/2}$ by the Cauchy--Schwarz inequality, producing the sandwich $C^x$ with total error $k(\delta+\eps)^{1/2}$.
 457	\end{proof}
