327	\begin{lemma}[Triangle inequality for ``$\simeq$''; Proposition 4.29 in \cite{Ji2020LowIndividualDegree}]\label{fact:triangle-for-simeq}
328		\lean{MIPStarRE.QPBT.consistencyDefect_trans_le}
329		\leanok
330		\uses{def:consistency}
331		If $A^x_a \ot \Id_B \simeq_{\eps} \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\gamma \Id_A \ot D^x_a$, then
332		\[
333			A^x_a \ot \Id_B \simeq_{\eps + 2\sqrt{\delta+\gamma}} \Id_A \ot D^x_a\,.
334		\]
335	\end{lemma}
336	\begin{proof}
337		\uses{fact:agreement}
338		Stated in the source without proof; it is Proposition 4.29 of \cite{Ji2020LowIndividualDegree}. The two hypotheses involving $C$ convert, via Lemma~\ref{fact:agreement}, into state-dependent closeness of $C^x_a \ot \Id_B$ to both $\Id_A \ot B^x_a$ and $\Id_A \ot D^x_a$, hence of $\Id_A \ot B^x_a$ to $\Id_A \ot D^x_a$ at cost $O(\delta+\gamma)$. The first consistency then transfers from $B$ to $D$ by expanding the off-diagonal mass and applying the Cauchy--Schwarz inequality, which turns the squared-distance bound into the term $2\sqrt{\delta+\gamma}$.
339	\end{proof}
