341	\begin{lemma}[Data processing; Fact 4.26 in \cite{Natarajan2018NEEXP}]\label{fact:data-processing}
342		\lean{MIPStarRE.QPBT.consistencyDefect_postprocess_le}
343		\leanok
344		\uses{def:consistency, def:bracket}
345		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
346		\[
347			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
348		\]
349	\end{lemma}
350	\begin{proof}
351		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
352	\end{proof}
