353	\begin{theorem}\label{prop:easy-approx-from-approx-delta}
354		\lean{MIPStarRE.LDT.Preliminaries.easyApproxFromApproxDelta}
355		\leanok
356		\uses{def:submeasurement, def:approx_delta}
357		Let $A = \{A^x_a\}$, $B = \{B^x_a\}$, and $C = \{C^x_a\}$ be submeasurements such that $A^x_a \approx_{\delta} B^x_a$. Then
358		\begin{equation*}
359			\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a  C^{\bx}_a \ket{\psi}
360			\approx_{\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a  C^{\bx}_a \ket{\psi}.
361		\end{equation*}
362	\end{theorem}
363	\begin{proof}
364		\leanok
365		The difference has magnitude
366		\[
367			\Big| \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a) C^{\bx}_a \ket{\psi}\Big|.
368		\]
369		By Cauchy--Schwarz this is at most
370		\[
371			\Big(\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^2 \ket{\psi}\Big)^{1/2}
372			\Big(\E_{\bx} \sum_a \bra{\psi} (C^{\bx}_a)^2 \ket{\psi}\Big)^{1/2}.
373		\]
374		The first factor is at most $\sqrt{\delta}$ by hypothesis, and the second is at most $1$ because $C$ is a submeasurement.
375	\end{proof}

